const menus={admin:[['home','Обзор'],['games','Игры и сезоны'],['round','Туры и задания'],['people','Участники'],['works','Работы'],['judges','Судьи'],['results','Результаты'],['diplomas','Дипломы'],['messages','Уведомления'],['support','Поддержка'],['access','Доступ и роли']],judge:[['home','Мои назначения'],['compare','Сравнение работ'],['completed','Завершённые'],['support','Поддержка']],moderator:[['home','Назначенные Игры'],['works','Проверка работ'],['support','Поддержка']],participant:[['home','Кабинет участника']]};
const names={admin:'Администратор',judge:'Судья',moderator:'Модератор',participant:'Участник'};let role='admin',page='home',votes=0,fieldConfig={photo:true,link:true,linkRequired:false,theme:false,reference:false};const content=document.querySelector('#content');const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const btn=(text,go)=>`<button data-go="${go}">${text}</button>`;const card=(title,text,action)=>`<section class="card"><h2>${title}</h2><div>${text}</div>${action||''}</section>`;
