const seasons=[{id:'s1',name:'Сезон 1'}];const games=[{id:'g1',season:'s1',name:'Игра 01'}];const rounds=[{id:'r3',game:'g1',number:3,name:'Портрет-персонаж',instructions:'Создайте образ и сдайте запрошенные материалы.',fields:{...fieldConfig}}];let seasonId='s1',gameId='g1',roundId='r3';
const currentSeason=()=>seasons.find(s=>s.id===seasonId);const currentGame=()=>games.find(g=>g.id===gameId);const currentRound=()=>rounds.find(r=>r.id===roundId);const choose=(label,type,id)=>`<button data-pick="${type}" data-id="${escape(id)}">${escape(label)}</button>`;
function crumbs(){let items=[btn('Сезоны','seasons')];if(currentSeason()&&page!=='seasons'&&page!=='create-season')items.push(btn(escape(currentSeason().name),'season'));if(currentGame()&&['game','game-settings','game-admission','game-admission-preview','game-people','person','create-round','round','preview','works','work-detail','work-edit','result-detail','result-history','comparison-detail','judges','assign-judge','judge-preview','results','results-preview','diplomas','diploma-detail','people'].includes(page))items.push(btn(escape(currentGame().name),'game'));if(currentRound()&&['round','preview'].includes(page))items.push(btn('Тур '+currentRound().number,'round'));return '<nav class="row crumbs" aria-label="Путь">'+items.join('<span aria-hidden="true">›</span>')+'</nav>';}
const renderBeforeHierarchy=render;
render=function(){renderBeforeHierarchy();if(role!=='admin')return;let html=null;
if(page==='home')html='<h1>Управление лигой</h1><p class="muted">Сезоны → Игры → Туры. Все действия в этом прототипе условные.</p><div class="grid">'+card('Сезоны','Откройте сезон, выберите Игру и её туры.',btn('Открыть сезоны','seasons'))+card('Участники','Пользователи и история участия.',btn('Участники','people'))+card('Сообщения','Уведомления и поддержка — отдельные разделы.',btn('Уведомления','messages')+' '+btn('Поддержка','support'))+card('Доступ и роли','Рабочие права и назначения.',btn('Доступ и роли','access'))+'</div>';
if(page==='seasons')html='<div class="row"><h1>Сезоны</h1>'+btn('Создать сезон','create-season')+'</div>'+seasons.map(s=>card(escape(s.name),'<span class="badge">Демонстрационный сезон</span>',choose('Открыть сезон','season',s.id))).join('');
if(page==='season'){let owned=games.filter(g=>g.season===seasonId);html='<h1>'+escape(currentSeason().name)+'</h1><div class="row"><h2>Игры сезона</h2>'+btn('Создать Игру','create-game')+'</div>'+ (owned.length?owned.map(g=>card(escape(g.name),'Черновик · условия участия и расписание настраиваются внутри Игры.',choose('Открыть Игру','game',g.id))).join(''):card('Игр пока нет','Создайте первую Игру в этом сезоне.'));}
if(page==='game'){let owned=rounds.filter(r=>r.game===gameId);html='<h1>'+escape(currentGame().name)+'</h1><span class="badge">'+escape(currentSeason().name)+'</span><section class="card"><h2>Управление Игрой</h2><div class="row">'+btn('Условия участия','game-admission')+' '+btn('Сроки Игры','game-settings')+' '+btn('Участники','game-people')+' '+btn('Работы','works')+' '+btn('Судьи','judges')+' '+btn('Результаты','results')+' '+btn('Дипломы','diplomas')+'</div></section><div class="row"><h2>Туры Игры</h2>'+btn('Создать тур','create-round')+'</div>'+ (owned.length?owned.map(r=>card('Тур '+r.number+' · '+escape(r.name),'Черновик задания',choose('Открыть тур','round',r.id))).join(''):card('Туров пока нет','Создайте первый тур этой Игры.'));}
if(['create-season','create-game','create-round'].includes(page)){let type=page.replace('create-',''),names={season:'Создать сезон',game:'Создать Игру',round:'Создать тур'},cancel={season:'seasons',game:'season',round:'game'};html='<h1>'+names[type]+'</h1><section class="card"><p class="muted">'+(type==='season'?'Новый сезон':type==='game'?'Сезон: '+escape(currentSeason().name):'Игра: '+escape(currentGame().name))+'</p><form id="create-entity" data-type="'+type+'"><div class="field"><label for="entity-name">Название</label><input id="entity-name" maxlength="150" required></div><div class="row"><button class="primary" type="submit">Создать черновик</button><button type="button" data-go="'+cancel[type]+'">Отменить</button></div></form><p class="muted">Сохранится только в памяти прототипа до обновления страницы.</p></section>';}
if(html!==null)content.innerHTML=html;
if(page==='round'&&currentRound()){let r=currentRound();fieldConfig=r.fields;document.querySelector('#title').value=r.name;document.querySelector('#instructions').value=r.instructions;content.querySelector('h1').textContent='Тур '+r.number+' · '+r.name;content.querySelector('h2').textContent='Настройки тура';content.querySelectorAll('[data-field]').forEach(el=>el.checked=!!fieldConfig[el.dataset.field]);}
if(['seasons','season','game','round','preview','create-season','create-game','create-round','people','works','judges','results','diplomas'].includes(page)){content.insertAdjacentHTML('afterbegin',crumbs());document.querySelector('#navigation [data-go="seasons"]').setAttribute('aria-current','page');}
document.title=(content.querySelector('h1')?.textContent||'Обзор')+' · FPL';};
document.addEventListener('click',e=>{let b=e.target.closest('[data-pick]');if(!b)return;let type=b.dataset.pick,id=b.dataset.id;if(type==='season'){seasonId=id;gameId=null;roundId=null;page='season';}if(type==='game'){gameId=id;seasonId=currentGame().season;roundId=null;page='game';}if(type==='round'){roundId=id;gameId=currentRound().game;seasonId=currentGame().season;fieldConfig=currentRound().fields;page='round';}render();window.scrollTo(0,0);});
document.addEventListener('submit',e=>{if(e.target.id!=='create-entity')return;e.preventDefault();let name=document.querySelector('#entity-name').value.trim();if(!name)return;let type=e.target.dataset.type;if(type==='season'){seasonId='s'+(seasons.length+1);seasons.push({id:seasonId,name});gameId=null;roundId=null;page='season';}if(type==='game'){gameId='g'+(games.length+1);games.push({id:gameId,season:seasonId,name});roundId=null;page='game';}if(type==='round'){let number=Math.max(0,...rounds.filter(r=>r.game===gameId).map(r=>r.number))+1;roundId='r'+(rounds.length+1)+'-new';rounds.push({id:roundId,game:gameId,number,name,instructions:'',fields:{photo:true,link:false,linkRequired:false,theme:false,reference:false}});fieldConfig=currentRound().fields;page='round';}render();document.querySelector('#notice').textContent='Черновик создан в прототипе. База данных не менялась.';});
document.addEventListener('input',e=>{if(role==='admin'&&page==='round'&&currentRound()){if(e.target.id==='title')currentRound().name=e.target.value;if(e.target.id==='instructions')currentRound().instructions=e.target.value;}});
render();
const renderBeforeVisualRefinement=render;
render=function(){renderBeforeVisualRefinement();if(role!=='admin')return;
content.querySelectorAll('[data-go^="create-"]').forEach(button=>{button.classList.add('create-action');button.closest('.row')?.classList.add('page-heading');});
if(['seasons','season','game'].includes(page)){let rows=[...content.querySelectorAll(':scope > .card')].filter(el=>el.querySelector('[data-pick]'));if(rows.length){let list=document.createElement('div');list.className='entity-list';rows[0].before(list);rows.forEach(row=>list.append(row));}}
if(page==='game'){[...content.querySelectorAll(':scope > .card')].find(el=>el.querySelector('h2')?.textContent==='Управление Игрой')?.classList.add('game-controls');}
};render();
// Schedule values are local Moscow wall-clock times in this demonstration.
const gameDateFields=[['registrationOpen','Начало регистрации'],['registrationClose','Конец регистрации'],['gameOpen','Начало Игры'],['gameClose','Конец Игры']];
const roundDateFields=[['workOpen','Открытие задания'],['workClose','Срок сдачи работы']];
const prepDateFields=[['prepOpen','Открытие подготовки'],['prepClose','Срок сдачи темы / референса']];
const scheduleOf=obj=>obj.schedule||(obj.schedule={});
const dateInputs=(obj,fields)=>'<div class="schedule-grid">'+fields.map(([key,label])=>`<div class="field"><label for="date-${key}">${label}</label><input id="date-${key}" type="datetime-local" data-date="${key}" value="${escape(scheduleOf(obj)[key]||'')}"></div>`).join('')+'</div>';
const dateText=value=>value?value.slice(8,10)+'.'+value.slice(5,7)+'.'+value.slice(0,4)+' в '+value.slice(11,16):'Срок пока не установлен';
const scheduleSummary=(obj,fields)=>'<dl class="schedule-summary">'+fields.map(([key,label])=>`<dt>${label}</dt><dd>${escape(dateText(scheduleOf(obj)[key]))}</dd>`).join('')+'</dl>';
function scheduleError(obj,prep=false){let d=scheduleOf(obj);for(let [a,b,label] of [['registrationOpen','registrationClose','Регистрация'],['gameOpen','gameClose','Игра'],['workOpen','workClose','Сдача работы'],...(prep?[['prepOpen','prepClose','Подготовка к туру']]:[])])if(d[a]&&d[b]&&d[b]<=d[a])return label+': окончание должно быть позже начала.';if(prep&&d.prepClose&&d.workOpen&&d.prepClose>d.workOpen)return 'Срок сдачи темы / референса должен быть не позже открытия задания.';return '';}
const renderBeforeSchedule=render;
render=function(){renderBeforeSchedule();if(role!=='admin')return;
if(page==='game-settings'&&currentGame()){content.innerHTML=crumbs()+'<h1>Сроки Игры</h1>'+card(escape(currentGame().name),'<p class="muted">Все даты и время — московские (МСК, UTC+3).</p>'+dateInputs(currentGame(),gameDateFields)+'<p class="schedule-error" role="alert"></p><p class="muted">Изменения сохраняются только в этом окне прототипа до обновления страницы.</p>',btn('К Игре','game'));}
if(page==='round'&&currentRound()){let r=currentRound();content.querySelector('h2').insertAdjacentHTML('afterend','<p class="muted">Все даты и время — московские (МСК, UTC+3).</p>');content.querySelector('[data-go="preview"]').insertAdjacentHTML('beforebegin','<section class="schedule-block"><h3>Сроки тура</h3>'+dateInputs(r,roundDateFields)+'</section><section id="prep-schedule" class="schedule-block" '+(!(r.fields.theme||r.fields.reference)?'hidden':'')+'><h3>Подготовка к туру</h3><p class="muted">Отдельный этап для темы или референса до открытия задания.</p>'+dateInputs(r,prepDateFields)+'</section><p class="schedule-error" role="alert"></p>');let old=[...content.querySelectorAll('p')].find(p=>p.textContent.startsWith('У подготовки'));if(old)old.textContent='Сданную работу можно заменить до срока сдачи. Тема или референс сдаётся отдельно.';}
if(page==='preview'&&currentRound()){let r=currentRound();content.querySelector('h1').insertAdjacentHTML('afterend','<section class="card"><h2>'+escape(r.name)+'</h2><p class="instructions-preview">'+escape(r.instructions||'Инструкции пока не добавлены.')+'</p><p class="muted">Все даты и время — московские (МСК, UTC+3).</p></section>');let sections=[...content.querySelectorAll('.card')];let prep=sections.find(x=>x.querySelector('h2')?.textContent==='До тура · подготовка');if(prep){prep.querySelector('h2').textContent='Подготовка к туру';prep.querySelector('h2').insertAdjacentHTML('afterend',scheduleSummary(r,prepDateFields));}let work=sections.find(x=>x.querySelector('h2')?.textContent==='Сдача работы');work?.querySelector('h2').insertAdjacentHTML('afterend',scheduleSummary(r,roundDateFields));}
updateScheduleError();};
function updateScheduleError(){let obj=page==='game-settings'?currentGame():page==='round'?currentRound():null;if(!obj)return;let error=scheduleError(obj,page==='round'&&(obj.fields.theme||obj.fields.reference));let el=content.querySelector('.schedule-error');if(el)el.textContent=error;let preview=content.querySelector('[data-go="preview"]');if(preview)preview.disabled=!!error;}
document.addEventListener('input',e=>{if(e.target.dataset.date){let obj=page==='game-settings'?currentGame():currentRound();if(obj)scheduleOf(obj)[e.target.dataset.date]=e.target.value;updateScheduleError();}});
document.addEventListener('change',e=>{if(page==='round'&&['theme','reference'].includes(e.target.dataset.field)){document.querySelector('#prep-schedule').hidden=!(fieldConfig.theme||fieldConfig.reference);updateScheduleError();}});
render();
// Editable per-Game eligibility settings; preview only, never admits a real user.
const leagueLabels={bronze:'Бронзовая',silver:'Серебряная',gold:'Золотая'};
const admissionOf=g=>g.admission||(g.admission={filterLeagues:false,leagues:['bronze','silver','gold'],limitEnabled:false,capacity:''});
function admissionError(a){if(a.filterLeagues&&!a.leagues.length)return 'Выберите хотя бы одну доступную лигу.';if(a.limitEnabled&&(!/^\d+$/.test(a.capacity)||Number(a.capacity)<1||Number(a.capacity)>100000))return 'Укажите целый лимит участников от 1 до 100 000.';return '';}
const renderBeforeAdmission=render;
render=function(){renderBeforeAdmission();if(role!=='admin'||!currentGame())return;let g=currentGame(),a=admissionOf(g);
if(page==='game-admission')content.innerHTML=crumbs()+'<h1>Условия участия</h1>'+card(escape(g.name),'<p class="muted">Участник записывается автоматически, если регистрация открыта и условия выполнены.</p><h3>Доступные лиги</h3><label class="check"><input type="checkbox" id="filter-leagues" '+(a.filterLeagues?'checked':'')+'>Ограничить участие по лигам</label><div id="league-options" '+(!a.filterLeagues?'hidden':'')+'>'+Object.entries(leagueLabels).map(([key,label])=>'<label class="check"><input type="checkbox" data-league="'+key+'" '+(a.leagues.includes(key)?'checked':'')+'>'+label+'</label>').join('')+'</div><p class="muted">Без ограничения по лигам могут записаться участники любой лиги. При включённом фильтре проверяется лига участника в этом сезоне.</p><h3>Количество участников</h3><label class="check"><input type="checkbox" id="limit-enabled" '+(a.limitEnabled?'checked':'')+'>Установить лимит участников</label><div id="capacity-field" class="field" '+(!a.limitEnabled?'hidden':'')+'><label for="capacity">Лимит участников</label><input id="capacity" type="number" min="1" max="100000" step="1" value="'+escape(a.capacity)+'"><p class="muted">Когда все места заняты, запись закрывается.</p></div><p class="admission-error" role="alert"></p><p class="muted">Настройки сохраняются только в этом окне прототипа до обновления страницы.</p>','<div class="row"><button class="primary" data-go="game-admission-preview">Предпросмотр условий</button>'+btn('К Игре','game')+'</div>');
if(page==='game-admission-preview')content.innerHTML=crumbs()+'<h1>Условия глазами участника</h1><p class="muted">Пример карточки Игры. Запись и проверка реального участника здесь не выполняются.</p>'+card(escape(g.name),'<dl class="schedule-summary"><dt>Кто может участвовать</dt><dd>'+(a.filterLeagues?a.leagues.map(k=>leagueLabels[k]).join(', '):'Участники любой лиги')+'</dd><dt>Количество мест</dt><dd>'+(a.limitEnabled?escape(a.capacity):'Без ограничения')+'</dd></dl>'+scheduleSummary(g,gameDateFields)+'<p>Если регистрация открыта, ваша лига подходит и есть свободное место, вы записываетесь автоматически.</p>',btn('К условиям участия','game-admission'));
if(['game-admission','game-admission-preview'].includes(page)){document.title=(content.querySelector('h1')?.textContent||'Условия участия')+' · FPL';document.querySelector('#navigation [data-go="seasons"]').setAttribute('aria-current','page');}updateAdmissionError();};
function updateAdmissionError(){if(page!=='game-admission'||!currentGame())return;let error=admissionError(admissionOf(currentGame()));content.querySelector('.admission-error').textContent=error;content.querySelector('[data-go="game-admission-preview"]').disabled=!!error;}
document.addEventListener('change',e=>{if(page!=='game-admission'||!currentGame())return;let a=admissionOf(currentGame());if(e.target.id==='filter-leagues'){a.filterLeagues=e.target.checked;content.querySelector('#league-options').hidden=!a.filterLeagues;}if(e.target.id==='limit-enabled'){a.limitEnabled=e.target.checked;content.querySelector('#capacity-field').hidden=!a.limitEnabled;}if(e.target.dataset.league){let key=e.target.dataset.league;a.leagues=e.target.checked?[...new Set([...a.leagues,key])]:a.leagues.filter(k=>k!==key);}updateAdmissionError();});
document.addEventListener('input',e=>{if(page==='game-admission'&&e.target.id==='capacity'){admissionOf(currentGame()).capacity=e.target.value;updateAdmissionError();}});
render();
// Fictional participant fixtures, distinct from TEST database records.
const demoPeople=[
{id:'p1',name:'Анна Примерова',league:'bronze',city:'Москва',email:'anna@example.test'},
{id:'p2',name:'Мария Образцова',league:'silver',city:'Казань',email:'maria@example.test'},
{id:'p3',name:'Елена Демонстрационная',league:'gold',city:'Самара',email:null},
{id:'p4',name:'Ольга Тестовая',league:'bronze',city:'Тула',email:'olga@example.test'}];
const demoEntries=[
{person:'p1',game:'g1',status:'participating',payment:'Оплачено',work:'Сдана',updated:'08.10.2026 в 11:20'},
{person:'p2',game:'g1',status:'registered',payment:'Оплачено',work:'Ожидает старта',updated:null},
{person:'p3',game:'g1',status:'noncompetitive',payment:'Оплата не требуется',work:'Ещё не сдана',updated:null},
{person:'p4',game:'g1',status:'exited',payment:'Оплачено',exitReason:'Выбыл после тура 2',work:'Участие прекращено',updated:null}];
const entryLabels={registered:'Зарегистрирован',participating:'Участник',noncompetitive:'Вне конкурса',exited:'Вышел / выбыл'};
const entrySummaryLabels={registered:'Зарегистрированы',participating:'Участники',noncompetitive:'Вне конкурса',exited:'Вышли / выбыли'};
let selectedPerson=null,personReturn='people',peopleSearch='',peopleLeague='',peopleStatus='';
function peopleRows(){
let scoped=page==='game-people',all=demoPeople.filter(p=>!scoped||demoEntries.some(e=>e.person===p.id&&e.game===gameId));
let rows=all.filter(p=>{let entry=demoEntries.find(e=>e.person===p.id&&e.game===gameId);return (!peopleLeague||p.league===peopleLeague)&&(!peopleSearch||[p.name,p.city,p.email||''].join(' ').toLocaleLowerCase('ru').includes(peopleSearch.toLocaleLowerCase('ru')))&&(!scoped||!peopleStatus||entry?.status===peopleStatus);});
let list=content.querySelector('#people-list');if(!list)return;
if(scoped){let summary=content.querySelector('#people-summary');if(summary)summary.innerHTML=Object.entries(entrySummaryLabels).map(([key,label])=>{let count=demoEntries.filter(e=>e.game===gameId&&e.status===key).length;return `<button class="summary-tile" data-status-filter="${key}" aria-pressed="${peopleStatus===key}"><strong>${count}</strong><span>${label}</span></button>`;}).join('');let statusSelect=content.querySelector('#people-status');if(statusSelect)statusSelect.value=peopleStatus;}
if(!rows.length)list.innerHTML='<div class="empty-list"><h2>Участники не найдены</h2><p>Попробуйте изменить поиск или фильтры.</p></div>';
else if(scoped)list.innerHTML='<table class="participants-table"><caption class="visually-hidden">Участники выбранной Игры</caption><thead><tr><th scope="col">Участник</th><th scope="col">Лига</th><th scope="col">Статус участия</th><th scope="col">Оплата</th><th scope="col">Работа · Тур 3</th></tr></thead><tbody>'+rows.map(p=>{let e=demoEntries.find(e=>e.person===p.id&&e.game===gameId);return `<tr><td data-label="Участник"><button class="person-name" data-person="${p.id}" aria-label="Открыть карточку: ${escape(p.name)}">${escape(p.name)}</button><small>${escape(p.city)}</small></td><td data-label="Лига">${escape(leagueLabels[p.league])}</td><td data-label="Статус участия"><span class="status-chip status-${e.status}">${entryLabels[e.status]}</span>${e.exitReason?'<small>'+escape(e.exitReason)+'</small>':''}</td><td data-label="Оплата">${escape(e.payment)}</td><td data-label="Работа · Тур 3">${escape(e.work)}</td></tr>`;}).join('')+'</tbody></table>';
else list.innerHTML=rows.map(p=>'<article class="person-row"><div><h2>'+escape(p.name)+'</h2><p>'+escape(leagueLabels[p.league])+' лига · '+escape(p.city)+'</p><span class="badge">'+(p.email?'Аккаунт активирован':'Без email · не активирован')+'</span></div><button data-person="'+p.id+'" aria-label="Открыть карточку: '+escape(p.name)+'">Открыть</button></article>').join('');
content.querySelector('#people-count').textContent='Показано '+rows.length+' из '+all.length;
}
const renderBeforePeople=render;
render=function(){renderBeforePeople();if(role!=='admin')return;
if(page==='people'||page==='game-people'){let scoped=page==='game-people';content.innerHTML=(scoped?crumbs():'')+'<h1>'+(scoped?'Участники Игры':'Участники лиги')+'</h1><p class="muted">'+(scoped?escape(currentGame().name)+' · ':'')+'Вымышленные участники для проверки интерфейса.</p>'+(scoped?'<div id="people-summary" class="people-summary" aria-label="Сводка по статусам"></div><p class="muted summary-hint">Нажмите на статус, чтобы отфильтровать список. Числа — по всей Игре.</p>':'')+'<div class="people-filters"><div class="field"><label for="people-search">Поиск участника</label><input id="people-search" type="search" placeholder="Имя, город или email" value="'+escape(peopleSearch)+'"></div><div class="field"><label for="people-league">Лига</label><select id="people-league"><option value="">Все лиги</option>'+Object.entries(leagueLabels).map(([key,label])=>'<option value="'+key+'" '+(peopleLeague===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div>'+(scoped?'<div class="field"><label for="people-status">Статус участия</label><select id="people-status"><option value="">Все статусы</option>'+Object.entries(entryLabels).map(([key,label])=>'<option value="'+key+'" '+(peopleStatus===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div>':'')+'</div><button class="filter-reset" data-reset-people>Сбросить фильтры</button><p id="people-count" class="muted" aria-live="polite"></p><div id="people-list" class="people-list"></div>'+(scoped?btn('К Игре','game'):btn('К обзору','home'));peopleRows();}
if(page==='person'&&selectedPerson){let p=demoPeople.find(p=>p.id===selectedPerson),scoped=personReturn==='game-people',entries=demoEntries.filter(e=>e.person===p.id&&(!scoped||e.game===gameId));content.innerHTML=(scoped?crumbs():'')+'<h1>'+escape(p.name)+'</h1><p class="muted">Демонстрационная карточка · сведения вымышлены.</p>'+card('Профиль','<dl><dt>Лига в Сезоне 1</dt><dd>'+escape(leagueLabels[p.league])+'</dd><dt>Город</dt><dd>'+escape(p.city)+'</dd><dt>Email</dt><dd>'+escape(p.email||'Не указан')+'</dd><dt>Аккаунт</dt><dd>'+(p.email?'Активирован':'Не активирован · пользователь импортирован без email')+'</dd></dl>')+card(scoped?'Участие в Игре':'Игры участника',entries.map(e=>{let g=games.find(g=>g.id===e.game);return '<section class="entry-detail"><h3>'+escape(g.name)+'</h3><p><span class="badge">'+entryLabels[e.status]+'</span></p><p>Оплата: '+escape(e.payment)+'</p>'+(e.exitReason?'<p>'+escape(e.exitReason)+'</p>':'')+'<h3>Работа · Тур 3</h3><p>'+escape(e.work)+'</p>'+(e.updated?'<p class="muted">Последняя сохранённая версия: '+e.updated+'</p>':'')+'<p class="muted">Фото, ссылка и история замен появятся при подключении работ. В этом прототипе файлы отсутствуют.</p></section>';}).join('')||'<p>Участий пока нет.</p>')+btn(scoped?'К участникам Игры':'К списку участников',personReturn);}
if(['people','game-people','person'].includes(page)){if(page==='game-people'||(page==='person'&&personReturn==='game-people'))document.querySelector('#navigation [data-go="seasons"]').setAttribute('aria-current','page');document.title=(content.querySelector('h1')?.textContent||'Участники')+' · FPL';if(page==='people'||(page==='person'&&personReturn==='people')){document.querySelectorAll('#navigation [aria-current]').forEach(e=>e.removeAttribute('aria-current'));document.querySelector('#navigation [data-go="people"]').setAttribute('aria-current','page');}}
};
document.addEventListener('click',e=>{let b=e.target.closest('[data-person]');if(!b)return;selectedPerson=b.dataset.person;personReturn=page;page='person';render();window.scrollTo(0,0);});
document.addEventListener('input',e=>{if(e.target.id==='people-search'){peopleSearch=e.target.value;peopleRows();}});
document.addEventListener('change',e=>{if(e.target.id==='people-league')peopleLeague=e.target.value;if(e.target.id==='people-status')peopleStatus=e.target.value;if(['people-league','people-status'].includes(e.target.id))peopleRows();});
render();

document.addEventListener('click',e=>{let filter=e.target.closest('[data-status-filter]'),reset=e.target.closest('[data-reset-people]');if(filter&&page==='game-people'){peopleStatus=peopleStatus===filter.dataset.statusFilter?'':filter.dataset.statusFilter;peopleRows();}if(reset&&['people','game-people'].includes(page)){peopleSearch='';peopleLeague='';peopleStatus='';content.querySelector('#people-search').value='';content.querySelector('#people-league').value='';peopleRows();}});
render();
// Synthetic work versions; local previews do not contain participant photographs.
const demoWorkVersions=[{person:'p1',round:'r3',versions:[{number:1,saved:'07.10.2026 в 17:30',photo:true,link:'https://example.test/demo/work-1'},{number:2,saved:'08.10.2026 в 11:20',photo:true,link:'https://example.test/demo/work-2'}]}];
let worksRoundId=null,worksSearch='',worksStatus='',worksLeague='',selectedWorkPerson=null,selectedWorkVersion=null;
const workRound=()=>rounds.find(r=>r.id===worksRoundId&&r.game===gameId);
const workVersions=p=>demoWorkVersions.find(w=>w.person===p&&w.round===worksRoundId)?.versions||[];
const workState=p=>{const r=workRound();if(!r)return 'missing';const item=FPLGalleryModel.composition(r,demoPeople,demoEntries,demoWorkVersions).find(w=>w.person.id===p);return !item?.version?'missing':item.ready?'submitted':'incomplete';};
const demoPreparation=[{person:'p1',round:'r3',theme:true,reference:true}];
const materialMark=(requested,saved,optional=false)=>!requested?'<span class="material-unused">Не требуется</span>':saved?'<span class="status-chip status-participating">Сдано</span>':'<span class="status-chip status-registered">Не сдано</span>'+(optional?'<small>Необязательно</small>':'');
const workLabels={submitted:'Сдана',missing:'Ещё не сдана',incomplete:'Неполная сдача'};
function workRows(){let r=workRound(),list=content.querySelector('#works-list');if(!list)return;let all=r?demoPeople.filter(p=>demoEntries.some(e=>e.person===p.id&&e.game===gameId&&['participating','noncompetitive'].includes(e.status))):[];let filtered=all.filter(p=>(!worksSearch||p.name.toLocaleLowerCase('ru').includes(worksSearch.toLocaleLowerCase('ru')))&&(!worksStatus||worksStatus===workState(p.id))&&(!worksLeague||p.league===worksLeague));content.querySelector('#works-count').textContent='Показано '+filtered.length+' из '+all.length;content.querySelector('#works-summary').innerHTML=r?Object.entries(workLabels).map(([key,label])=>`<button class="summary-tile" data-work-filter="${key}" aria-pressed="${worksStatus===key}"><strong>${all.filter(p=>(!worksLeague||p.league===worksLeague)&&workState(p.id)===key).length}</strong><span>${label}</span></button>`).join(''):'';content.querySelector('#works-status').value=worksStatus;content.querySelector('#works-league').value=worksLeague;content.querySelector('#works-leagues-summary').innerHTML=Object.entries(leagueLabels).map(([key,label])=>{let group=all.filter(p=>p.league===key),submitted=group.filter(p=>workState(p.id)==='submitted').length;return `<button class="summary-tile league-tile" data-work-league="${key}" aria-pressed="${worksLeague===key}"><span>${label} лига</span><strong>${submitted}<small> / ${group.length}</small></strong><span>сдано / участников тура</span></button>`;}).join('');
list.innerHTML=!r?'<div class="empty-list"><h2>Туров пока нет</h2><p>Создайте тур внутри Игры.</p></div>':!filtered.length?'<div class="empty-list"><h2>Работы не найдены</h2><p>Измените фильтры или выберите другой тур.</p></div>':'<table class="participants-table works-table"><caption class="visually-hidden">Сдача работ в выбранном туре</caption><thead><tr><th scope="col">Участник</th><th scope="col">Превью</th><th scope="col">Участие</th><th scope="col">Подготовка</th><th scope="col">Фото</th><th scope="col">Ссылка</th><th scope="col">Последняя версия</th></tr></thead><tbody>'+filtered.map(p=>{let e=demoEntries.find(e=>e.person===p.id&&e.game===gameId),vs=workVersions(p.id),v=vs.at(-1),prep=demoPreparation.find(item=>item.person===p.id&&item.round===r.id),prepRequested=r.fields.theme||r.fields.reference,prepSaved=(!r.fields.theme||prep?.theme)&&(!r.fields.reference||prep?.reference);return `<tr><td data-label="Участник"><button class="person-name" data-open-work="${p.id}" aria-label="Открыть работу: ${escape(p.name)}">${escape(p.name)}</button><small>${leagueLabels[p.league]} лига</small></td><td data-label="Превью">${v?.photo&&r.fields.photo?`<button class="thumbnail-button" data-open-work="${p.id}" aria-label="Открыть превью: ${escape(p.name)}"><img class="work-thumbnail" src="${escape(v.photoSrc||(`assets/demo-face-v${Math.min(v.number,2)}.svg`))}" alt="Демонстрационная иллюстрация работы"></button>`:'<span class="thumbnail-empty">Нет фото</span>'}</td><td data-label="Участие">${entryLabels[e.status]}</td><td data-label="Подготовка">${materialMark(prepRequested,prepSaved)}</td><td data-label="Фото">${materialMark(r.fields.photo,v?.photo)}</td><td data-label="Ссылка">${materialMark(r.fields.link,v?.link,!r.fields.linkRequired&&r.fields.photo)}</td><td data-label="Последняя версия">${v?escape(v.saved)+'<small>Версия '+v.number+'</small>':'—'}</td></tr>`;}).join('')+'</tbody></table>';
}
const renderBeforeWorks=render;
render=function(){renderBeforeWorks();if(role!=='admin'||!['works','work-detail'].includes(page))return;
if(!currentGame()){content.innerHTML='<h1>Работы</h1>'+card('Выберите Игру','Работы просматриваются внутри Игры и тура.',btn('Открыть сезоны','seasons'));return;}
let owned=rounds.filter(r=>r.game===gameId);if(!workRound())worksRoundId=owned[0]?.id||null;let r=workRound();
if(page==='works')content.innerHTML=crumbs()+'<h1>Работы</h1><p class="muted">'+escape(currentGame().name)+' · Демонстрационные сдачи. Фото и ссылки — примеры.</p><div class="field"><label for="works-round">Тур</label><select id="works-round">'+(owned.length?owned.map(r=>`<option value="${r.id}" ${r.id===worksRoundId?'selected':''}>Тур ${r.number} · ${escape(r.name)}</option>`).join(''):'<option value="">Туров нет</option>')+'</select></div><div id="works-leagues-summary" class="people-summary leagues-summary"></div><div id="works-summary" class="people-summary work-summary"></div><p class="muted">Показываем конкурсных участников и участников вне конкурса. Сводка по лигам — по выбранному туру. Нажмите на лигу для фильтрации. Тема и референс не считаются сдачей работы.</p><div class="people-filters"><div class="field"><label for="works-search">Поиск по имени</label><input type="search" id="works-search" value="'+escape(worksSearch)+'"></div><div class="field"><label for="works-status">Статус работы</label><select id="works-status"><option value="">Все работы</option>'+Object.entries(workLabels).map(([key,label])=>`<option value="${key}" ${worksStatus===key?'selected':''}>${label}</option>`).join('')+'</select></div><div class="field"><label for="works-league">Лига</label><select id="works-league"><option value="">Все лиги</option>'+Object.entries(leagueLabels).map(([key,label])=>`<option value="${key}" ${worksLeague===key?'selected':''}>${label}</option>`).join('')+'</select></div></div><button class="filter-reset" data-reset-works>Сбросить фильтры</button><p id="works-count" class="muted" aria-live="polite"></p><div id="works-list" class="people-list"></div>'+btn('К Игре','game');
if(page==='works')workRows();
if(page==='work-detail'&&r){let p=demoPeople.find(p=>p.id===selectedWorkPerson),vs=workVersions(p.id),v=vs.find(v=>v.number===selectedWorkVersion)||vs.at(-1),latest=vs.at(-1);content.innerHTML=crumbs()+'<h1>Работа участника</h1><p>'+escape(p.name)+' · Тур '+r.number+'</p><p class="muted">Демонстрационная карточка. Реальных фотографий и внешних публикаций нет.</p>'+card(v?(v===latest?'Текущая сданная версия':'Предыдущая версия'):'Работа ещё не сдана',v?'<p><span class="badge">Версия '+v.number+'</span> · '+escape(v.saved)+'</p>'+(r.fields.photo?'<div class="work-preview">'+(v.photo?'<img src="'+escape(v.photoSrc||('assets/demo-face-v'+Math.min(v.number,2)+'.svg'))+'" alt="Демонстрационная иллюстрация работы">':'Фото отсутствует')+'</div>':'')+(r.fields.link?'<h3>Ссылка на публикацию</h3><p class="demo-link">'+escape(v.link||'Не добавлена')+'</p><p class="muted">Пример адреса, переход отключён.</p>':''):'<p>Участник пока не сохранил сдачу в этом туре.</p>')+card('Сроки и замена',scheduleSummary(r,roundDateFields)+'<p>До срока сдачи участник может сохранить замену. Пока замена не сохранена, действует предыдущая сданная версия.</p>')+(vs.length?card('История версий','<div class="version-list">'+[...vs].reverse().map(version=>`<button data-work-version="${version.number}" aria-pressed="${v===version}">Версия ${version.number} · ${version.saved}${version===latest?' · текущая':''}</button>`).join('')+'</div>'):'')+btn('К списку работ','works');}
document.querySelectorAll('#navigation [aria-current]').forEach(el=>el.removeAttribute('aria-current'));document.querySelector('#navigation [data-go="works"]').setAttribute('aria-current','page');document.title=(content.querySelector('h1')?.textContent||'Работы')+' · FPL';};
document.addEventListener('input',e=>{if(e.target.id==='works-search'){worksSearch=e.target.value;workRows();}});
document.addEventListener('change',e=>{if(e.target.id==='works-league'){worksLeague=e.target.value;workRows();}if(e.target.id==='works-status'){worksStatus=e.target.value;workRows();}if(e.target.id==='works-round'){worksRoundId=e.target.value;render();}});
document.addEventListener('click',e=>{let open=e.target.closest('[data-open-work]'),version=e.target.closest('[data-work-version]'),filter=e.target.closest('[data-work-filter]'),reset=e.target.closest('[data-reset-works]');if(open){selectedWorkPerson=open.dataset.openWork;selectedWorkVersion=null;page='work-detail';render();window.scrollTo(0,0);}if(version){selectedWorkVersion=Number(version.dataset.workVersion);render();}if(filter){worksStatus=worksStatus===filter.dataset.workFilter?'':filter.dataset.workFilter;workRows();}if(reset){worksSearch='';worksStatus='';worksLeague='';content.querySelector('#works-search').value='';workRows();}});
render();

document.addEventListener('click',e=>{let b=e.target.closest('[data-work-league]');if(b){worksLeague=worksLeague===b.dataset.workLeague?'':b.dataset.workLeague;workRows();}});
