// Advancement quotas belong to the round, independently for each league.
function advancementDecision(rows,person,count){
 if(count===undefined||count===null)return 'Не задано';
 if(count===0)return 'Не проходит';
 const score=x=>Number(String(x.score).replace(',','.'));
 const ordered=[...rows].sort((a,b)=>score(b)-score(a));
 const entry=ordered.find(x=>x.person===person);if(!entry)return 'Не задано';
 if(count>=ordered.length)return 'Проходит';
 const boundary=score(ordered[count-1]);
 if(boundary===score(ordered[count])&&score(entry)===boundary)return 'Нужен тай-брейк';
 return score(entry)>=boundary?'Проходит':'Не проходит';
}
function advancementFor(x){return resultStage()==='waiting'?'Ожидаем оценивания':advancementDecision(allRoundResults().filter(row=>row.league===x.league),x.person,resultRound()?.advanceCounts?.[x.league]);}
function advancementHasTie(){return allRoundResults().some(x=>advancementFor(x)==='Нужен тай-брейк');}
