function notificationRecipients(d){const ids=new Set();return demoEntries.filter(e=>e.game===d.game&&(!d.status||e.status===d.status)).flatMap(e=>{const p=demoPeople.find(p=>p.id===e.person);if(!p||ids.has(p.id)||(d.league&&p.league!==d.league))return [];ids.add(p.id);return [{id:p.id,name:p.name,league:p.league,status:e.status}];});}
function notificationText(d){return '<article class="notification-preview"><small>Уведомление в личном кабинете</small><h2>'+escape(d.title)+'</h2><p>'+escape(d.body)+'</p></article>';}
function notificationAudience(d,recipients){return '<section class="card"><h2>Получатели · '+recipients.length+'</h2><p class="muted">'+escape(games.find(g=>g.id===d.game)?.name||'Игра')+' · '+(d.league?leagueLabels[d.league]+' лига':'Все лиги')+' · '+(d.status?entryLabels[d.status]:'Все статусы')+'</p>'+(recipients.length?'<div class="notification-recipient-list">'+recipients.map(p=>'<div><span>'+escape(p.name)+'</span><small>'+leagueLabels[p.league]+' · '+entryLabels[p.status]+'</small></div>').join('')+'</div>':'<p role="alert">По этим условиям получателей нет. Измените выбор.</p>')+'</section>';}
const renderBeforeNotifications=render;
render=function(){renderBeforeNotifications();if(role!=='admin'||!['messages','message-compose','message-preview','message-detail'].includes(page))return;
 if(page==='messages')content.innerHTML='<div class="row page-heading"><h1>Уведомления</h1><button class="primary" data-new-notification>Создать уведомление</button></div><p class="muted">Сообщения участникам в личном кабинете. Обращения в поддержку находятся в отдельном разделе.</p>'+(adminNotifications.length?'<div class="people-list"><table class="participants-table"><caption class="visually-hidden">Список уведомлений</caption><thead><tr><th>Сообщение</th><th>Игра</th><th>Получатели</th><th>Состояние</th><th>Действие</th></tr></thead><tbody>'+[...adminNotifications].reverse().map(n=>`<tr><td data-label="Сообщение">${escape(n.title)}<small class="diploma-number">${escape(n.at)}</small></td><td data-label="Игра">${escape(games.find(g=>g.id===n.game)?.name||'Игра')}</td><td data-label="Получатели">${n.recipients.length}</td><td data-label="Состояние">${n.sent?'Отправка показана в прототипе':'Черновик'}</td><td data-label="Действие"><button data-notification="${n.id}">Просмотреть</button></td></tr>`).join('')+'</tbody></table></div>':card('Уведомлений пока нет','Создайте сообщение и проверьте получателей перед отправкой.'))+'<p class="muted">Прототип не отправляет сообщения. Черновики и история сохраняются только до перезагрузки.</p>';
 if(page==='message-compose'){const d=notificationDraft;content.innerHTML='<h1>Новое уведомление</h1><form id="notification-compose"><section class="card"><h2>Кому</h2><div class="people-filters"><div class="field"><label for="notification-game">Игра</label><select id="notification-game" name="game">'+games.map(g=>`<option value="${g.id}" ${d.game===g.id?'selected':''}>${escape(g.name)}</option>`).join('')+'</select></div><div class="field"><label for="notification-league">Лига</label><select id="notification-league" name="league"><option value="">Все лиги</option>'+Object.entries(leagueLabels).map(([k,v])=>`<option value="${k}" ${d.league===k?'selected':''}>${v}</option>`).join('')+'</select></div><div class="field"><label for="notification-status">Участие</label><select id="notification-status" name="status"><option value="">Все статусы</option>'+Object.entries(entryLabels).map(([k,v])=>`<option value="${k}" ${d.status===k?'selected':''}>${v}</option>`).join('')+'</select></div></div><p id="notification-recipient-count" aria-live="polite">Получателей: '+notificationRecipients(d).length+'</p><p class="muted">Канал: уведомления в личном кабинете.</p></section><section class="card"><h2>Сообщение</h2><div class="field"><label for="notification-title">Заголовок</label><input id="notification-title" name="title" required maxlength="150" value="'+escape(d.title)+'"></div><div class="field"><label for="notification-body">Текст</label><textarea id="notification-body" name="body" required maxlength="5000" rows="6">'+escape(d.body)+'</textarea></div></section><div class="row"><button class="primary" type="submit">Проверить перед отправкой</button><button type="button" data-go="messages">К списку</button></div></form>';
 }
 if(page==='message-preview'){const d=notificationDraft,recipients=notificationRecipients(d);content.innerHTML='<h1>Проверка уведомления</h1><p class="muted">Так сообщение будет выглядеть у участника. Ниже — полный список получателей.</p>'+notificationText(d)+notificationAudience(d,recipients)+'<div class="row"><button data-go="message-compose">Редактировать</button><button data-save-notification>Сохранить черновик</button><button class="primary" data-demo-send-notification '+(!recipients.length?'disabled':'')+'>Имитировать отправку</button></div><p class="muted">Имитируется только состояние интерфейса. Настоящая доставка не выполняется.</p>';}
 if(page==='message-detail'){const n=adminNotifications.find(n=>n.id===selectedNotification);content.innerHTML='<h1>Уведомление</h1>'+(n?'<p class="muted">'+(n.sent?'Отправка показана в прототипе':'Черновик')+' · '+escape(n.at)+'</p>'+notificationText(n)+notificationAudience(n,n.recipients)+(!n.sent?'<button data-edit-notification="'+n.id+'">Продолжить редактирование</button>':''):card('Сообщение не найдено','Вернитесь к списку.'))+btn('К уведомлениям','messages');}
 document.querySelectorAll('#navigation [aria-current]').forEach(el=>el.removeAttribute('aria-current'));document.querySelector('#navigation [data-go="messages"]').setAttribute('aria-current','page');document.title=(content.querySelector('h1')?.textContent||'Уведомления')+' · FPL';
};
document.addEventListener('input',e=>{if(e.target.closest('#notification-compose')&&e.target.name){notificationDraft[e.target.name]=e.target.value;const count=content.querySelector('#notification-recipient-count');if(count)count.textContent='Получателей: '+notificationRecipients(notificationDraft).length;}});
document.addEventListener('change',e=>{if(e.target.closest('#notification-compose')&&e.target.name){notificationDraft[e.target.name]=e.target.value;content.querySelector('#notification-recipient-count').textContent='Получателей: '+notificationRecipients(notificationDraft).length;}});
document.addEventListener('submit',e=>{if(e.target.id!=='notification-compose')return;e.preventDefault();notificationDraft.title=notificationDraft.title.trim();notificationDraft.body=notificationDraft.body.trim();if(!notificationDraft.title||!notificationDraft.body)return;page='message-preview';render();window.scrollTo(0,0);});
document.addEventListener('click',e=>{if(e.target.closest('[data-new-notification]')){notificationDraft={game:currentGame()?.id||games[0]?.id||'',league:'',status:'participating',title:'',body:''};page='message-compose';render();}
 const view=e.target.closest('[data-notification]'),edit=e.target.closest('[data-edit-notification]');if(view){selectedNotification=view.dataset.notification;page='message-detail';render();}if(edit){const n=adminNotifications.find(n=>n.id===edit.dataset.editNotification);if(n&&!n.sent){notificationDraft={game:n.game,league:n.league,status:n.status,title:n.title,body:n.body,id:n.id,targetMode:n.targetMode,people:[...(n.people||[])],channels:[...(n.channels||['cabinet'])]};page='message-compose';render();}}
 const send=e.target.closest('[data-demo-send-notification]'),save=e.target.closest('[data-save-notification]');if(send||save){const recipients=notificationRecipients(notificationDraft);if(send&&!recipients.length)return;const n={...notificationDraft,id:notificationDraft.id||'notice-'+(adminNotifications.length+1),recipients,sent:!!send,at:nowMoscow()};const index=adminNotifications.findIndex(x=>x.id===n.id);if(index>=0)adminNotifications[index]=n;else adminNotifications.push(n);selectedNotification=n.id;page='message-detail';render();document.querySelector('#notice').textContent=send?'Отправка показана только в прототипе. Настоящие сообщения не отправлялись.':'Черновик сохранён в памяти прототипа.';}
});
render();

// Configurable notification prototype; Telegram connections here are illustrative only.
const demoTelegramConnections=new Set(['p1','p2','p5','p9']);
const notificationEvents={results:'Опубликованы результаты',round:'Открылся тур',preparation:'Открылась подготовка',deadline:'Приближается срок сдачи',diploma:'Выпущен диплом',support:'Получен ответ поддержки'};
const notificationRules=[];let editingNotificationRule=null;
const notificationRecipientsBeforeIndividuals=notificationRecipients;
notificationRecipients=function(d){if(d.targetMode!=='people')return notificationRecipientsBeforeIndividuals(d);const selected=new Set(d.people||[]);return demoPeople.filter(p=>selected.has(p.id)).map(p=>({id:p.id,name:p.name,league:p.league,status:demoEntries.find(e=>e.game===d.game&&e.person===p.id)?.status||'registered'}));};
const notificationChannels=d=>d.channels||['cabinet'];
function notificationTabs(){return '<div class="row notification-tabs" role="navigation" aria-label="Разделы уведомлений">'+[['messages','Сообщения'],['message-rules','Автоматические правила'],['message-history','История доставки']].map(([id,label])=>`<button data-go="${id}" ${page===id?'aria-current="page"':''}>${label}</button>`).join('')+'</div>';}
function channelControls(d){return '<fieldset class="notification-channel-fields"><legend>Куда отправить</legend>'+[['cabinet','Личный кабинет'],['telegram','Telegram']].map(([key,label])=>`<label class="check"><input type="checkbox" data-notification-channel="${key}" ${notificationChannels(d).includes(key)?'checked':''}>${label}</label>`).join('')+'<small>Telegram-подключения в этом примере вымышлены. Настоящий бот ещё не подключён.</small></fieldset>';}
function notificationChannelPreview(d,people){const telegram=people.filter(p=>demoTelegramConnections.has(p.id)).length;return '<section class="card"><h2>Каналы</h2><p>'+notificationChannels(d).map(c=>c==='cabinet'?'Личный кабинет: '+people.length:'Telegram: подключён у '+telegram+' из '+people.length).join('<br>')+'</p>'+ (notificationChannels(d).includes('telegram')&&telegram<people.length?'<p role="alert">У '+(people.length-telegram)+' получателей Telegram не подключён. В этот канал они сообщение не получат.</p>':'')+(!notificationChannels(d).length?'<p role="alert">Выберите хотя бы один канал.</p>':'')+'</section>';}
const renderBeforeNotificationAutomation=render;
render=function(){renderBeforeNotificationAutomation();if(role!=='admin'||!['messages','message-compose','message-preview','message-detail','message-rules','message-rule-edit','message-history'].includes(page))return;
 if(page==='message-compose'){
 const d=notificationDraft;content.querySelector('form').insertAdjacentHTML('afterbegin','<section class="card"><h2>Выбор получателей</h2><div class="field"><label for="notification-target-mode">Кому отправить</label><select id="notification-target-mode"><option value="group" '+(d.targetMode!=='people'?'selected':'')+'>Группа по условиям</option><option value="people" '+(d.targetMode==='people'?'selected':'')+'>Конкретные люди</option></select></div>'+(d.targetMode==='people'?'<div class="notification-person-picker">'+demoPeople.map(p=>`<label class="check"><input type="checkbox" data-notification-person="${p.id}" ${(d.people||[]).includes(p.id)?'checked':''}>${escape(p.name)}<small>${demoTelegramConnections.has(p.id)?'Telegram подключён · пример':'Telegram не подключён · пример'}</small></label>`).join('')+'</div>':'')+channelControls(d)+'</section>');
 if(d.targetMode==='people'){content.querySelector('#notification-league').closest('.field').hidden=true;content.querySelector('#notification-status').closest('.field').hidden=true;}
 }
 if(page==='message-preview'||page==='message-detail'){const d=page==='message-preview'?notificationDraft:adminNotifications.find(n=>n.id===selectedNotification);if(d){const people=page==='message-preview'?notificationRecipients(d):d.recipients;content.querySelector('.notification-preview').insertAdjacentHTML('afterend',notificationChannelPreview(d,people));if(d.targetMode==='people'){const audience=[...content.querySelectorAll('.card')].find(c=>c.querySelector('h2')?.textContent.startsWith('Получатели'));if(audience)audience.querySelector('.muted').textContent='Выбраны конкретные люди · '+escape(games.find(g=>g.id===d.game)?.name||'Без игры');}const send=content.querySelector('[data-demo-send-notification]');if(send)send.disabled=!people.length||!notificationChannels(d).length;}}
 if(page==='message-rules')content.innerHTML='<div class="row page-heading"><h1>Автоматические правила</h1><button class="primary" data-new-notification-rule>Создать правило</button></div><p class="muted">Событие → получатели → текст → каналы. Создайте правило один раз и включите его для нужной игры.</p>'+(notificationRules.length?'<div class="people-list"><table class="participants-table"><thead><tr><th>Событие / игра</th><th>Получатели</th><th>Каналы</th><th>Включено</th><th>Действие</th></tr></thead><tbody>'+notificationRules.map(r=>`<tr><td data-label="Событие / игра">${notificationEvents[r.event]}<small class="diploma-number">${escape(games.find(g=>g.id===r.game)?.name||'Игра')}</small></td><td data-label="Получатели">${r.league?leagueLabels[r.league]:'Все лиги'} · ${r.status?entryLabels[r.status]:'Все статусы'}</td><td data-label="Каналы">${notificationChannels(r).map(c=>c==='cabinet'?'Кабинет':'Telegram').join(', ')}</td><td data-label="Включено"><input aria-label="Включить правило ${escape(notificationEvents[r.event])}" type="checkbox" data-toggle-notification-rule="${r.id}" ${r.enabled?'checked':''}></td><td data-label="Действие"><button data-edit-notification-rule="${r.id}">Настроить</button></td></tr>`).join('')+'</tbody></table></div>':card('Правил пока нет','Например, уведомлять участников после публикации результатов.'))+'<p class="muted">В прототипе правила сохраняются до перезагрузки. Автоматическая отправка не запускается.</p>';
 if(page==='message-rule-edit'){
 const r=editingNotificationRule;content.innerHTML='<h1>Настройка правила</h1><form id="notification-rule-form"><section class="card"><div class="field"><label for="rule-game">Игра</label><select id="rule-game" name="game">'+games.map(g=>`<option value="${g.id}" ${r.game===g.id?'selected':''}>${escape(g.name)}</option>`).join('')+'</select></div><div class="field"><label for="rule-event">Событие</label><select id="rule-event" name="event">'+Object.entries(notificationEvents).map(([key,label])=>`<option value="${key}" ${r.event===key?'selected':''}>${label}</option>`).join('')+'</select></div><p class="muted">Результаты уведомляются после публикации. Диплом и ответ поддержки направляются своему получателю. Остальные правила применяются к участникам нужного тура.</p><div class="people-filters"><div class="field"><label for="rule-league">Лига</label><select id="rule-league" name="league"><option value="">Все лиги</option>'+Object.entries(leagueLabels).map(([k,v])=>`<option value="${k}" ${r.league===k?'selected':''}>${v}</option>`).join('')+'</select></div><div class="field"><label for="rule-status">Участие</label><select id="rule-status" name="status"><option value="">Все статусы</option>'+Object.entries(entryLabels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')+'</select></div><div class="field"><label for="rule-hours">Напомнить за часов до срока</label><input id="rule-hours" name="hours" type="number" min="1" max="720" step="1" value="'+r.hours+'" '+(r.event==='deadline'?'required':'disabled')+'></div></div><label class="check"><input type="checkbox" name="missingOnly" '+(r.missingOnly?'checked':'')+'>Для напоминания — только тем, кто не сдал обязательные материалы</label>'+channelControls(r)+'<div class="field"><label for="rule-title">Заголовок</label><input id="rule-title" name="title" required maxlength="150" value="'+escape(r.title)+'"></div><div class="field"><label for="rule-body">Текст</label><textarea id="rule-body" name="body" required maxlength="5000" rows="5">'+escape(r.body)+'</textarea></div><p class="muted">Можно использовать {игра} и {тур}. Номер тура подставляется из события.</p><label class="check"><input type="checkbox" name="enabled" '+(r.enabled?'checked':'')+'>Правило включено</label><p id="rule-error" role="alert"></p></section><div class="row"><button class="primary" type="submit">Сохранить правило</button><button type="button" data-go="message-rules">К правилам</button></div></form>';
 }
 if(page==='message-history'){const sent=adminNotifications.filter(n=>n.sent);sent.forEach(n=>{if(!n.deliveryExample)n.deliveryExample=n.recipients.flatMap(p=>notificationChannels(n).map(channel=>({name:p.name,title:n.title,game:n.game,channel,at:n.at,status:channel==='telegram'&&!demoTelegramConnections.has(p.id)?'Пропущено: Telegram не подключён':'Имитация · доставка не проверялась'})));});const deliveries=sent.flatMap(n=>n.deliveryExample);content.innerHTML='<h1>История доставки</h1><p class="muted">Отдельная запись для каждого человека и канала. Все записи здесь демонстрационные.</p>'+(deliveries.length?'<div class="people-list"><table class="participants-table"><thead><tr><th>Получатель</th><th>Сообщение / игра</th><th>Канал</th><th>Состояние</th></tr></thead><tbody>'+deliveries.map(d=>`<tr><td data-label="Получатель">${escape(d.name)}</td><td data-label="Сообщение / игра">${escape(d.title)}<small class="diploma-number">${escape(games.find(g=>g.id===d.game)?.name||'Игра')} · ${escape(d.at)}</small></td><td data-label="Канал">${d.channel==='telegram'?'Telegram':'Кабинет'}</td><td data-label="Состояние">${d.status}</td></tr>`).join('')+'</tbody></table></div>':card('Доставок пока нет','Записи появятся после имитации отправки ручного сообщения.'));}
 content.insertAdjacentHTML('afterbegin',notificationTabs());document.querySelectorAll('#navigation [aria-current]').forEach(el=>el.removeAttribute('aria-current'));document.querySelector('#navigation [data-go="messages"]').setAttribute('aria-current','page');document.title=(content.querySelector('h1')?.textContent||'Уведомления')+' · FPL';
};
document.addEventListener('change',e=>{const target=e.target;if(target.id==='notification-target-mode'){notificationDraft.targetMode=target.value;render();}if(target.dataset.notificationPerson){const selected=new Set(notificationDraft.people||[]);target.checked?selected.add(target.dataset.notificationPerson):selected.delete(target.dataset.notificationPerson);notificationDraft.people=[...selected];content.querySelector('#notification-recipient-count').textContent='Получателей: '+notificationRecipients(notificationDraft).length;}
 if(target.dataset.notificationChannel){const d=page==='message-rule-edit'?editingNotificationRule:notificationDraft,channels=new Set(notificationChannels(d));target.checked?channels.add(target.dataset.notificationChannel):channels.delete(target.dataset.notificationChannel);d.channels=[...channels];}if(target.dataset.toggleNotificationRule){const r=notificationRules.find(r=>r.id===target.dataset.toggleNotificationRule);if(r)r.enabled=target.checked;}if(target.id==='rule-event'){content.querySelector('#rule-hours').disabled=target.value!=='deadline';content.querySelector('#rule-hours').required=target.value==='deadline';}});
document.addEventListener('click',e=>{if(e.target.closest('[data-new-notification-rule]')){editingNotificationRule={id:null,game:currentGame()?.id||games[0]?.id,event:'results',league:'',status:'participating',hours:24,missingOnly:true,channels:['cabinet'],enabled:false,title:'Результаты опубликованы',body:'Результаты {игра}, тур {тур}, доступны в вашем кабинете.'};page='message-rule-edit';render();}const edit=e.target.closest('[data-edit-notification-rule]');if(edit){const r=notificationRules.find(r=>r.id===edit.dataset.editNotificationRule);editingNotificationRule={...r,channels:[...r.channels]};page='message-rule-edit';render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='notification-rule-form')return;e.preventDefault();const form=e.target,r={...editingNotificationRule};for(const key of ['game','event','league','status','title','body'])r[key]=form.elements.namedItem(key).value.trim();r.hours=Number(form.elements.namedItem('hours').value);r.missingOnly=form.elements.namedItem('missingOnly').checked;r.enabled=form.elements.namedItem('enabled').checked;if(!r.channels.length){content.querySelector('#rule-error').textContent='Выберите хотя бы один канал.';return;}if(!r.title||!r.body)return;r.id=r.id||'rule-'+(notificationRules.length+1);const index=notificationRules.findIndex(x=>x.id===r.id);if(index>=0)notificationRules[index]=r;else notificationRules.push(r);page='message-rules';render();document.querySelector('#notice').textContent='Правило сохранено только в прототипе. Настоящая отправка не подключена.';});
render();

document.addEventListener('click',e=>{if(e.target.closest('[data-demo-send-notification]')&&!notificationChannels(notificationDraft).length){e.preventDefault();e.stopImmediatePropagation();}},true);

// Separate support inbox with local demonstration conversation history.
