leagueLabels.bronze='Bronze';leagueLabels.silver='Silver';leagueLabels.gold='Gold';
const ruLeague={'Бронзов':'Bronze','Серебрян':'Silver','Золот':'Gold'};
function fixLeagueStr(t){t=t.replace(/(^|[^А-Яа-яЁё])(Bronze|Silver|Gold) лига/g,(m,b,l)=>b+'Лига '+l);return t.replace(/(Bronze|Silver|Gold) (лига|лиги|лиге|лигу|лигой)(?![а-я])/g,'$2 $1').replace(/(Бронзов|Серебрян|Золот)(ая|ой|ую) (лига|лиги|лиге|лигу)(?![а-я])/g,(m,a,b,c)=>c+' '+ruLeague[a]).replace(/Бронзовая, Серебряная, Золотая/g,'Bronze, Silver, Gold').replace(/(^|[.!?:]\s+|·\s|—\s|\(|\n\s*)лиг(а|и|е|у)(?= (Bronze|Silver|Gold))/g,(m,p,e)=>p+'Лиг'+e);}
function fixLeagues(root){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){const t=n.nodeValue;if(!/(Bronze|Silver|Gold|Бронзов|Серебрян|Золот)/.test(t))continue;let v=fixLeagueStr(t);if(/^\s*лиг[аиеу] (Bronze|Silver|Gold)/.test(v)&&!(n.previousSibling&&/\S$/.test(n.previousSibling.textContent||'')))v=v.replace(/^(\s*)л/,'$1Л');if(v!==t)n.nodeValue=v;}}
const diplomaSvgBeforeLeague=diplomaSvg;diplomaSvg=function(d){return fixLeagueStr(diplomaSvgBeforeLeague(d)).replace(/>лига (Bronze|Silver|Gold)/g,'>Лига $1');};
