const DEFAULT_PRIZES=[['1 место в каждой лиге','Главный приз лиги'],['2–3 место в каждой лиге','Приз призёра'],['TOP WORK тура','Публикация работы в соцсетях лиги'],['Все, кто прошёл Игру','Диплом участника']];
function prizesOf(g){if(!g.prizes)g.prizes=DEFAULT_PRIZES.map(x=>x.slice());return g.prizes;}
function prizesEditor(g){const list=prizesOf(g);return '<section class="card prizes-card"><h2>Призы Игры</h2><p class="muted">Показываются участникам в описании Игры — на странице записи и на странице Игры.</p><div class="prize-rows">'
 +list.map((x,i)=>'<div class="prize-row"><div class="field"><label for="pz-w-'+i+'">За что</label><input id="pz-w-'+i+'" data-prize-w="'+i+'" value="'+escape(x[0])+'"></div><div class="field"><label for="pz-p-'+i+'">Приз</label><input id="pz-p-'+i+'" data-prize-p="'+i+'" value="'+escape(x[1])+'"></div><button type="button" data-prize-del="'+i+'" aria-label="Убрать строку '+(i+1)+'">Убрать</button></div>').join('')
 +'</div><div class="row"><button type="button" data-prize-add>Добавить приз</button><button type="button" class="primary" data-prize-save>Сохранить призы</button></div><p class="muted" id="prize-note" aria-live="polite"></p></section>';}
function finalOf(r){if(!r.finalFormula)r.finalFormula={path:40,fin:60,pairNoRating:true};return r.finalFormula;}
function finalBlock(r){const f=finalOf(r);return '<section class="card final-formula"><h2>Итог финала</h2><p class="muted">Итог Игры = доля «пути» по турам 1–4 + доля финальной работы, в сумме 100%. Место в Игре считается по этому итогу.</p><div class="ff-row"><div class="field"><label for="ff-path">Путь по турам 1–4, %</label><input id="ff-path" type="number" min="0" max="100" step="5" value="'+f.path+'"></div><div class="field"><label for="ff-fin">Финальная работа, %</label><input id="ff-fin" type="number" min="0" max="100" step="5" value="'+f.fin+'"></div></div><label class="check"><input type="checkbox" id="ff-pair"'+(f.pairNoRating?' checked':'')+'>Парный финал на рейтинг FPL не влияет</label><p class="muted" id="ff-note">Сейчас: '+f.path+'% путь + '+f.fin+'% финал. Так это видит участник в итоге Игры.</p></section>';}
const renderBeforeOwner1012=render;
render=function(){renderBeforeOwner1012();
 if(role==='admin'&&page==='game'&&currentGame()&&!content.querySelector('.prizes-card')){content.insertAdjacentHTML('beforeend','<h2 class="game-set-h">Призы и скидки</h2>'+prizesEditor(currentGame()));}
 if(role==='admin'&&page==='round'){const r=currentRound();if(r&&r.number===5&&!content.querySelector('.final-formula')){const blocks=[...content.querySelectorAll('section,.card')].filter(x=>x.parentElement===content||x.parentElement?.parentElement===content);const anchor=blocks.find(x=>/Как оценивают|Оценивание|Судейство/.test(x.querySelector('h2,h3')?.textContent||''))||blocks[1]||content.querySelector('h1');anchor.insertAdjacentHTML('afterend',finalBlock(r));}}
 if(role==='admin'&&page==='assign-judge'&&!content.querySelector('.judge-rule')){const f=content.querySelector('#assign-judge-form');if(f){const players=new Set(demoEntries.filter(e=>e.game===gameId).map(e=>personName(e.person)));[...f.querySelectorAll('#assignment-judge option')].forEach(o=>{if(o.value&&players.has(o.textContent))o.remove();});f.insertAdjacentHTML('beforebegin','<p class="muted judge-rule">Участник этой Игры не может быть её судьёй — участники Игры в списке не показываются.</p>');}}
 if(role==='admin'&&page==='diplomas'){content.querySelectorAll('.dip-rules ul').forEach(ul=>{ul.innerHTML='<li>Диплом один для всех — «за прохождение Игры». Его получает каждый, кто сдал все работы Игры (в конкурсе или вне конкурса).</li><li>На дипломе: публичное имя, если участник его указал, иначе полное имя; город; лига; сезон и Игра с датами; номер, QR-код для проверки и дата.</li><li>У занявших 1, 2 и 3 место в своей лиге на дипломе есть место и лига; у остальных — лига. «Игра засчитана» на дипломе не пишется.</li><li>Номер: FPL-S1-01-G-0001 — сезон 1, Игра 01, лига (G — Gold, S — Silver, B — Bronze), порядковый номер внутри лиги.</li><li>Номера присваиваются всем сразу при подведении итога Игры.</li>';});
  content.querySelectorAll('.dip-rules summary').forEach(x=>{x.textContent='Кому положен диплом и что на нём написано';});}
};
document.addEventListener('click',e=>{
 const add=e.target.closest('[data-prize-add]');if(add){prizesOf(currentGame()).push(['','']);render();const ins=content.querySelectorAll('[data-prize-w]');if(ins.length)ins[ins.length-1].focus();return;}
 const del=e.target.closest('[data-prize-del]');if(del){prizesOf(currentGame()).splice(+del.dataset.prizeDel,1);render();return;}
 const sv=e.target.closest('[data-prize-save]');if(sv){const g=currentGame();g.prizes=prizesOf(g).filter(x=>x[0].trim()||x[1].trim());render();const n=content.querySelector('#prize-note');const k=g.prizes.length;if(n)n.textContent='Сохранено: '+k+' '+(k%10===1&&k%100!==11?'строка':[2,3,4].includes(k%10)&&![12,13,14].includes(k%100)?'строки':'строк')+'. В прототипе — до обновления страницы.';}
});
document.addEventListener('input',e=>{const t=e.target;
 if(t.dataset&&t.dataset.prizeW!==undefined)prizesOf(currentGame())[+t.dataset.prizeW][0]=t.value;
 if(t.dataset&&t.dataset.prizeP!==undefined)prizesOf(currentGame())[+t.dataset.prizeP][1]=t.value;
 if(t.id==='ff-path'||t.id==='ff-fin'){const f=finalOf(currentRound()),v=Math.max(0,Math.min(100,+t.value||0));if(t.id==='ff-path'){f.path=v;f.fin=100-v;const o=content.querySelector('#ff-fin');if(o)o.value=f.fin;}else{f.fin=v;f.path=100-v;const o=content.querySelector('#ff-path');if(o)o.value=f.path;}const n=content.querySelector('#ff-note');if(n)n.textContent='Сейчас: '+f.path+'% путь + '+f.fin+'% финал. Так это видит участник в итоге Игры.';}
});
document.addEventListener('change',e=>{if(e.target.id==='ff-pair')finalOf(currentRound()).pairNoRating=e.target.checked;});
render();
/* ===== Скидки участникам по окончании Игры (решение владельца 12.10): правила «кому», коды из InSales или списком ===== */
const DISC_WHO=[['all','Всем, кто прошёл Игру'],['p1','1 место в лиге'],['p23','2–3 место в лиге'],['p13','1–3 место в лиге'],['bronze','Лига Bronze'],['silver','Лига Silver'],['gold','Лига Gold']];
const discounts={g1:{mode:'all',rules:[
 {who:'all',value:'10%',until:'2026-11-30',source:'insales',codes:[]},
 {who:'p13',value:'20%',until:'2026-11-30',source:'list',codes:['FPL01-PRIZE-7KX2','FPL01-PRIZE-M4QA','FPL01-PRIZE-T9ZD','FPL01-PRIZE-2HWE','FPL01-PRIZE-B8NC','FPL01-PRIZE-Q3LP','FPL01-PRIZE-V6RJ']}]}};
let discPreview=false;
function discOf(g){if(!discounts[g.id])discounts[g.id]={mode:'all',rules:[{who:'all',value:'10%',until:'',source:'list',codes:[]}]};return discounts[g.id];}
function discFinishers(){return diplomaExamples.filter(d=>d.game===gameId&&d.eligible);}
function discMatch(rule,d){const w=rule.who;if(w==='all')return true;if(w==='p1')return d.place===1;if(w==='p23')return d.place===2||d.place===3;if(w==='p13')return d.place>=1&&d.place<=3;return d.league===w;}
function discPlan(g){const c=discOf(g),fin=discFinishers(),used=c.rules.map(()=>0),out=[];
 fin.forEach(d=>{const got=[];c.rules.forEach((r,i)=>{if(c.mode==='first'&&got.length)return;if(!discMatch(r,d))return;let code;if(r.source==='insales')code='код создаст кабинет';else{code=r.codes[used[i]]||null;used[i]++;}got.push({rule:i,value:r.value,code});});out.push({d,got});});
 return {out,need:c.rules.map((r,i)=>fin.filter(d=>discMatch(r,d)).length),used};}
const whoLabel=w=>(DISC_WHO.find(x=>x[0]===w)||['',''])[1];
function discHtml(g){const c=discOf(g),plan=discPlan(g),fin=discFinishers();
 const recv=i=>{let n=0;plan.out.forEach(x=>{if(x.got.some(y=>y.rule===i))n++;});return n;};
 return '<section class="card disc-card"><h2>Скидки участникам по окончании Игры</h2><p class="muted">Раздаются автоматически при подведении итога Игры — вместе с номерами дипломов. Участник видит код в итогах Игры и в уведомлениях (в Telegram — если он включён). Каждый код выдаётся одному человеку.</p>'
 +'<div class="disc-rules">'+c.rules.map((r,i)=>{const need=recv(i),have=r.codes.length,short=r.source==='list'&&have<need;
  return '<div class="disc-rule"><div class="disc-grid"><div class="field"><label for="dr-who-'+i+'">Кому</label><select id="dr-who-'+i+'" data-disc="who" data-i="'+i+'">'+DISC_WHO.map(([v,l])=>'<option value="'+v+'"'+(r.who===v?' selected':'')+'>'+l+'</option>').join('')+'</select></div>'
  +'<div class="field"><label for="dr-val-'+i+'">Скидка</label><input id="dr-val-'+i+'" data-disc="value" data-i="'+i+'" value="'+escape(r.value)+'" placeholder="10%"></div>'
  +'<div class="field"><label for="dr-until-'+i+'">Действует до</label><input id="dr-until-'+i+'" type="date" data-disc="until" data-i="'+i+'" value="'+escape(r.until)+'"></div>'
  +'<div class="field"><label for="dr-src-'+i+'">Коды</label><select id="dr-src-'+i+'" data-disc="source" data-i="'+i+'"><option value="insales"'+(r.source==='insales'?' selected':'')+'>Создать коды и загрузить в InSales</option><option value="list"'+(r.source==='list'?' selected':'')+'>Загрузить список из InSales</option></select></div></div>'
  +(r.source==='list'?'<div class="field"><label for="dr-codes-'+i+'">Коды, по одному в строке</label><textarea id="dr-codes-'+i+'" data-disc="codes" data-i="'+i+'" rows="3" placeholder="FPL01-XXXX">'+escape(r.codes.join('\n'))+'</textarea></div><div class="row"><label class="file-btn">Загрузить файл CSV<input type="file" accept=".csv,.txt" data-disc-file="'+i+'" hidden></label></div>':'<p class="muted small disc-note">Кабинет создаст '+need+' '+(need%10===1&&need%100!==11?'код':[2,3,4].includes(need%10)&&![12,13,14].includes(need%100)?'кода':'кодов')+' со скидкой '+escape(r.value||'—')+' и сроком до '+(r.until?matDate(r.until+'T23:59'):'—')+' и загрузит их в магазин через API InSales (одноразовые). Состояние подключения — ниже.</p>')
  +'<div class="disc-foot"><span class="status-chip '+(short?'status-exited':'status-participating')+'">Получат: '+need+(r.source==='list'?' · кодов '+have+(short?' — не хватает '+(need-have):''):'')+'</span><button type="button" data-disc-del="'+i+'">Убрать правило</button></div></div>';}).join('')+'</div>'
 +'<div class="row"><button type="button" data-disc-add>Добавить правило</button></div>'
 +'<fieldset class="disc-mode"><legend>Если участник подходит под несколько правил</legend><label class="check"><input type="radio" name="disc-mode" value="all"'+(c.mode==='all'?' checked':'')+'>Выдать все его скидки</label><label class="check"><input type="radio" name="disc-mode" value="first"'+(c.mode==='first'?' checked':'')+'>Только одну — первую подходящую по списку</label></fieldset>'
 +'<div class="row"><button type="button" class="primary" data-disc-preview>'+(discPreview?'Скрыть':'Показать')+', кто что получит</button></div>'
 +(discPreview?'<div class="table-wrap"><table class="disc-table"><thead><tr><th>Участник</th><th>Лига</th><th>Место</th><th>Скидки</th></tr></thead><tbody>'+plan.out.map(x=>'<tr><td data-label="Участник">'+escape(personName(x.d.person))+'</td><td data-label="Лига">'+leagueLabels[x.d.league]+'</td><td data-label="Место">'+(x.d.place||'—')+'</td><td data-label="Скидки">'+(x.got.length?x.got.map(y=>escape(y.value)+' · '+(y.code?escape(y.code):'<b class="warn-text">кода нет</b>')).join('<br>'):'—')+'</td></tr>').join('')+'</tbody></table></div><p class="muted small">Всего прошли Игру: '+fin.length+'. Список строится по тем же данным, что и реестр дипломов.</p>':'')
 +'<div class="insales-box"><b>InSales</b> <span class="status-chip status-exited">Не подключён</span><p class="muted small">Для подключения нужен ключ доступа магазина (в InSales: «Приложения» → «Разработчикам» → «Создать ключ доступа») и адрес магазина. Ключ вводится на сервере кабинета, в чат его не присылать. Без подключения работает загрузка списка кодов.</p></div>'+'<details class="disc-msg"><summary>Текст сообщения участнику</summary><p>Спасибо за {Игра}! Ваша скидка {скидка} в магазине: <b>{код}</b>. Действует до {дата}. Код вводится при оформлении заказа.</p></details></section>';}
/* событие в наборе автоматических уведомлений */
autoRules.forEach(([g,list])=>{if(g==='Результаты и дипломы'&&!list.some(r=>r[0]==='discount'))list.push(['discount','Скидка за прохождение Игры','получившие скидку','при подведении итога Игры','KT','Спасибо за {Игра}! Ваша скидка {скидка}: {код}. Действует до {дата}.']);});
autoOn.discount=true;autoText.discount='Спасибо за {Игра}! Ваша скидка {скидка}: {код}. Действует до {дата}.';
const renderBeforeDisc=render;
render=function(){renderBeforeDisc();
 if(role==='admin'&&page==='game'&&currentGame()&&!content.querySelector('.disc-card')){const p=content.querySelector('.prizes-card');if(p)p.insertAdjacentHTML('afterend',discHtml(currentGame()));else content.insertAdjacentHTML('beforeend',discHtml(currentGame()));}
 if(role==='admin'&&page==='diplomas'&&currentGame()&&!content.querySelector('.disc-link')){const b=content.querySelector('.dip-actions');if(b)b.insertAdjacentHTML('afterend','<p class="muted disc-link">Вместе с номерами раздаются и скидки участникам — настройки на странице Игры. <button type="button" data-go="game">Скидки по окончании</button></p>');}
};
function discRerender(focusId){const y=window.scrollY;render();window.scrollTo(0,y);if(focusId){const el=document.getElementById(focusId);if(el)el.focus();}}
document.addEventListener('change',e=>{const t=e.target;if(!t.closest||!t.closest('.disc-card'))return;const c=discOf(currentGame());
 if(t.dataset.disc==='who'||t.dataset.disc==='source'||t.dataset.disc==='until'){c.rules[+t.dataset.i][t.dataset.disc]=t.value;discRerender(t.id);}
 if(t.name==='disc-mode'){c.mode=t.value;discRerender();}
 if(t.dataset.discFile!==undefined&&t.files&&t.files[0]){const i=+t.dataset.discFile,rd=new FileReader();rd.onload=()=>{const codes=String(rd.result).split(/[\r\n,;]+/).map(x=>x.trim()).filter(x=>x&&!/^(code|код)$/i.test(x));c.rules[i].codes=codes;discRerender('dr-codes-'+i);};rd.readAsText(t.files[0]);}
});
document.addEventListener('input',e=>{const t=e.target;if(!t.closest||!t.closest('.disc-card'))return;const c=discOf(currentGame());
 if(t.dataset.disc==='value')c.rules[+t.dataset.i].value=t.value;
 if(t.dataset.disc==='codes')c.rules[+t.dataset.i].codes=t.value.split(/\n+/).map(x=>x.trim()).filter(Boolean);
 discChips();
});
function discChips(){const g=currentGame();if(!g)return;const c=discOf(g),plan=discPlan(g);content.querySelectorAll('.disc-rule').forEach((el,i)=>{const r=c.rules[i];if(!r)return;let need=0;plan.out.forEach(x=>{if(x.got.some(y=>y.rule===i))need++;});const have=r.codes.length,short=r.source==='list'&&have<need,ch=el.querySelector('.disc-foot .status-chip');if(ch){ch.className='status-chip '+(short?'status-exited':'status-participating');ch.textContent='Получат: '+need+(r.source==='list'?' · кодов '+have+(short?' — не хватает '+(need-have):''):'');}});}
document.addEventListener('click',e=>{const c=currentGame()&&discOf(currentGame());if(!c)return;
 if(e.target.closest('[data-disc-add]')){c.rules.push({who:'gold',value:'15%',until:'',source:'list',codes:[]});discRerender('dr-who-'+(c.rules.length-1));}
 const del=e.target.closest('[data-disc-del]');if(del){c.rules.splice(+del.dataset.discDel,1);discRerender();}
 if(e.target.closest('[data-disc-preview]')){discPreview=!discPreview;discRerender();}
});
render();
